<script lang="ts">
 import {keyBindings,saveKeyBindings,keyChord,defaultKeyBindings} from './keyboard-shortcuts';import type {DesktopCommand} from './desktop-menu';import {translator} from './i18n';
 export let language:'ru'|'ro';export let menus:DesktopCommand[];let query='',error='';$:t=translator(language);
 function flatten(items:DesktopCommand[]):DesktopCommand[]{return items.flatMap(item=>item.children?flatten(item.children):item.action?[item]:[]);}
 $:commands=flatten(menus).filter(c=>c[language].toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 function assign(e:KeyboardEvent,action:string){e.preventDefault();e.stopPropagation();if(e.key==='Escape')return;const chord=e.key==='Backspace'||e.key==='Delete'?'':keyChord(e);if(!chord&&e.key!=='Backspace'&&e.key!=='Delete')return;if(chord&&Object.entries($keyBindings).some(([key,value])=>key!==action&&value===chord)){error=t('Эта комбинация уже назначена другой команде.','Combinația este deja atribuită altei comenzi.');return;}error='';saveKeyBindings({...$keyBindings,[action]:chord});}
</script>
<section class="keyboard-settings"><h2>{t('Сочетания клавиш','Comenzi rapide')}</h2><p>{t('Выберите поле команды и нажмите сочетание. Backspace удаляет назначение. Ctrl или Command обозначены Mod.','Selectați câmpul comenzii și apăsați combinația. Backspace elimină atribuirea. Ctrl sau Command este indicat prin Mod.')}</p><input aria-label={t('Поиск команды','Caută comandă')} placeholder={t('Поиск команды','Caută comandă')} bind:value={query}/>{#if error}<p role="alert">{error}</p>{/if}{#each commands as command}<label><span>{command[language]}</span><input readonly aria-label={command[language]} value={($keyBindings[command.action!]||'').replaceAll('Key','')} onkeydown={e=>assign(e,command.action!)}/></label>{/each}<button class="button secondary" onclick={()=>saveKeyBindings({...defaultKeyBindings})}>{t('Восстановить стандартные','Restabilește valorile implicite')}</button></section>
<style>.keyboard-settings{display:flex;flex-direction:column;gap:14px}.keyboard-settings label{display:grid;grid-template-columns:minmax(0,1fr) 200px;align-items:center;gap:16px}.keyboard-settings p{line-height:1.6}.keyboard-settings input{min-width:0}</style>
